// The API client. `api` is typed from the server's OpenAPI schema (api-schema.ts, generated by `pnpm gen:api` from
// openapi.json; see README.md), so a route or field the server does not have fails `pnpm typecheck`. `fetchJson` is the
// untyped transport for anything outside the schema. NEXT_PUBLIC_API_URL is the server's origin (e.g.
// http://127.0.0.1:8787). Empty means same origin, which is what the static export served by the API uses.

import createClient from "openapi-fetch";
import type { paths } from "@/lib/api-schema";

const BASE = (process.env.NEXT_PUBLIC_API_URL ?? "").replace(/\/$/, "");

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly path: string,
    readonly body: string,
  ) {
    super(`${status} from ${path}`);
    this.name = "ApiError";
  }
}

export function apiUrl(path: string): string {
  return `${BASE}${path.startsWith("/") ? path : `/${path}`}`;
}

/** GET (or `init.method`) `path` and parse the JSON reply as `T`. Throws ApiError on a non-2xx status. */
export async function fetchJson<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(apiUrl(path), {
    ...init,
    headers: { Accept: "application/json", ...(init?.body ? { "Content-Type": "application/json" } : {}), ...init?.headers },
  });
  if (!res.ok) throw new ApiError(res.status, path, await res.text());
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

/** The typed client: `api.GET("/jobs/{job_id}", { params: { path: { job_id } } })`. Wrap a call in `unwrap` for its data or an ApiError. */
export const api = createClient<paths>({ baseUrl: BASE });

/** The data of a typed `api` call, or an ApiError for a non-2xx reply (the same error `fetchJson` throws). */
export async function unwrap<T>(request: Promise<{ data?: T; error?: unknown; response: Response }>): Promise<T> {
  const { data, error, response } = await request;
  if (!response.ok) {
    throw new ApiError(response.status, new URL(response.url, "http://x").pathname, typeof error === "string" ? error : JSON.stringify(error));
  }
  return data as T;
}

/** Every `Services.emit(kind, payload)` on the server, as the API's `GET /events` SSE stream will send it. */
export type ApiEvent = { kind: string; payload: unknown };

/** Open the event stream and call `onEvent` for each event. Returns the function that closes it. */
export function subscribe(
  onEvent: (event: ApiEvent) => void,
  onError?: (error: Event) => void,
  onOpen?: () => void,
): () => void {
  const source = new EventSource(apiUrl("/events"));
  if (onOpen) source.onopen = onOpen;
  source.onmessage = (message: MessageEvent<string>) => {
    try {
      onEvent(JSON.parse(message.data) as ApiEvent);
    } catch {
      // a malformed frame is dropped; the next one is independent
    }
  };
  if (onError) source.onerror = onError;
  return () => source.close();
}
